import re


def slugify(text, sep="-", max_words=None):
    """Lowercase `text` and join its alphanumeric words with separators."""
    words = re.findall(r"[a-z0-9]+", text.lower())

    if max_words is not None:
        # Slicing handles the truncation, including returning an empty list if max_words=0
        words = words[:max_words]

    return sep.join(words)
