DEFAULTS = {"host": "localhost", "port": 8080, "debug": False}


def load_config(text):
    """Parse 'key = value' lines into a config dict."""
    # Start from a copy of DEFAULTS to ensure original is never modified.
    config = DEFAULTS.copy()

    lines = text.splitlines()
    for i, line in enumerate(lines):
        line_num = i + 1  # Line numbers are 1-based

        stripped_line = line.strip()

        # 1. Skip blank lines and lines that start with '#'
        if not stripped_line or stripped_line.startswith("#"):
            continue

        # 3. Split on the first '=' only
        parts = stripped_line.split("=", 1)

        # 5a. Raise ValueError for a line without '='
        if len(parts) != 2:
             raise ValueError(f"Missing '=' separator on line {line_num}")

        key, value_str = parts[0].strip(), parts[1].strip()

        # 5b. Raise ValueError for a key that is not in DEFAULTS
        if key not in DEFAULTS:
            raise ValueError(f"Unknown configuration key '{key}' on line {line_num}")

        converted_value = None

        try:
            # 4. Type conversions based on key
            if key == "port":
                converted_value = int(value_str)
            elif key == "debug":
                lower_val = value_str.lower()
                if lower_val == 'true':
                    converted_value = True
                elif lower_val == 'false':
                    converted_value = False
                else:
                    # 5c. Raise ValueError for invalid debug conversion
                    raise ValueError("Must be 'true' or 'false'")
            else:
                # For other keys (like host), keep as stripped string
                converted_value = value_str

        except ValueError as e:
            # Catches errors from int() conversion or the explicit error raised above
            msg = f"Cannot convert value '{value_str}' for key '{key}' on line {line_num}"
            raise ValueError(f"{msg}. Reason: {e}")

        config[key] = converted_value

    return config
