def summarize(rows):
    """rows: list of dicts with 'category' and 'amount' strings. Return {category: total}."""
    totals = {}
    for row in rows:
        # Handle category case-insensitively and ignore surrounding spaces
        raw_category = str(row.get("category", ""))
        category_clean = raw_category.strip().lower()

        # Skip rows whose category is empty after stripping whitespace
        if not category_clean:
            continue

        # Skip rows whose amount is empty or not a number
        raw_amount = row.get("amount")
        try:
            amount = float(str(raw_amount))
        except (ValueError, TypeError):
            continue  # Skip if conversion fails

        # Sum the amounts per category
        totals[category_clean] = totals.get(category_clean, 0) + amount

    # Round each total to 2 decimal places before returning
    return {k: round(v, 2) for k, v in totals.items()}
